<script>
(function () {
  'use strict';

  var CLAVE_MINIMA = 8;

  var formulario = document.getElementById('registro');
  var campos = {
    nombre: document.getElementById('nombre'),
    correo: document.getElementById('correo'),
    web: document.getElementById('web'),
    clave: document.getElementById('clave')
  };
  var correoAscii = document.getElementById('correo-ascii');
  var webAscii = document.getElementById('web-ascii');

  /* ---------- Nombres de dominio ---------- */

  // Convierte un dominio (U-labels o A-labels) a su forma ASCII con el
  // analizador de URL del navegador, que aplica UTS #46. Devuelve null si
  // el dominio no se puede convertir.
  function dominioAAscii(dominio) {
    if (dominio === '' || /[\s\/\\?#@:%\[\]]/u.test(dominio)) {
      return null;
    }
    try {
      return new URL('http://' + dominio + '/').hostname;
    } catch (e) {
      return null;
    }
  }

  // Comprueba un nombre de host ya convertido a ASCII: etiquetas de 1 a 63
  // octetos, 253 como máximo en total y un TLD de dos o más letras (sin
  // límite superior) o una A-label "xn--".
  function hostAsciiValido(host) {
    if (host.endsWith('.')) {
      host = host.slice(0, -1); // punto raíz final
    }
    if (host.length === 0 || host.length > 253) {
      return false;
    }
    var etiquetas = host.toLowerCase().split('.');
    if (etiquetas.length < 2) {
      return false;
    }
    for (var i = 0; i < etiquetas.length; i++) {
      var etiqueta = etiquetas[i];
      if (etiqueta.length < 1 || etiqueta.length > 63 ||
          etiqueta.startsWith('-') || etiqueta.endsWith('-')) {
        return false;
      }
    }
    var tld = etiquetas[etiquetas.length - 1];
    if (tld.startsWith('xn--')) {
      return tld.length > 4;
    }
    return /^[a-z]{2,}$/.test(tld);
  }

  /* ---------- Validadores: devuelven { error, ascii } ---------- */

  function validarNombre(valor) {
    if (valor.trim() === '') {
      return { error: 'Introduce tu nombre completo.' };
    }
    return { error: '' };
  }

  // Comprobación mínima: una sola arroba, parte local no vacía y sin
  // espacios (se admite Unicode, "+", "'", etc.) y un dominio válido.
  function validarCorreo(valor) {
    var correo = valor.trim();
    if (correo === '') {
      return { error: 'Introduce tu dirección de correo electrónico.' };
    }
    if (/\s/u.test(correo)) {
      return { error: 'La dirección de correo no puede contener espacios.' };
    }
    var partes = correo.split('@');
    if (partes.length !== 2) {
      return { error: 'La dirección debe contener una sola arroba (@).' };
    }
    var local = partes[0];
    var dominio = partes[1];
    if (local === '') {
      return { error: 'Falta la parte anterior a la arroba (@).' };
    }
    if (dominio === '') {
      return { error: 'Falta el dominio después de la arroba (@).' };
    }
    var ascii = dominio.endsWith('.') ? null : dominioAAscii(dominio);
    if (ascii === null || !hostAsciiValido(ascii)) {
      return {
        error: 'El dominio «' + dominio + '» no es válido. Ejemplo: nombre@ejemplo.es'
      };
    }
    return { error: '', ascii: local + '@' + ascii };
  }

  function validarWeb(valor) {
    var texto = valor.trim();
    if (texto === '') {
      return { error: '', ascii: '' }; // campo opcional
    }
    var mensaje = 'Introduce una dirección web válida, por ejemplo https://ejemplo.es';
    if (/\s/u.test(texto)) {
      return { error: 'La dirección web no puede contener espacios.' };
    }
    // Se admite "ejemplo.es" sin esquema: se asume https.
    var conEsquema = /^[a-z][a-z0-9+.\-]*:\/\//i.test(texto) ? texto : 'https://' + texto;
    var url;
    try {
      url = new URL(conEsquema);
    } catch (e) {
      return { error: mensaje };
    }
    if (url.protocol !== 'http:' && url.protocol !== 'https:') {
      return { error: 'La dirección web debe empezar por http:// o https://' };
    }
    if (!hostAsciiValido(url.hostname)) {
      return { error: mensaje };
    }
    return { error: '', ascii: url.href };
  }

  function validarClave(valor) {
    if (valor === '') {
      return { error: 'Introduce una contraseña.' };
    }
    if (Array.from(valor).length < CLAVE_MINIMA) {
      return { error: 'La contraseña debe tener al menos ' + CLAVE_MINIMA + ' caracteres.' };
    }
    return { error: '' };
  }

  var validadores = {
    nombre: validarNombre,
    correo: validarCorreo,
    web: validarWeb,
    clave: validarClave
  };

  /* ---------- Presentación de errores ---------- */

  function mostrarResultado(clave, resultado) {
    var campo = campos[clave];
    var zonaError = document.getElementById('error-' + clave);
    zonaError.textContent = resultado.error;
    if (resultado.error) {
      campo.setAttribute('aria-invalid', 'true');
    } else {
      campo.removeAttribute('aria-invalid');
    }
  }

  function validarCampo(clave) {
    var resultado = validadores[clave](campos[clave].value);
    mostrarResultado(clave, resultado);
    return resultado;
  }

  Object.keys(campos).forEach(function (clave) {
    var campo = campos[clave];

    // Al salir de un campo ya rellenado, se comprueba.
    campo.addEventListener('blur', function () {
      if (campo.value !== '') {
        validarCampo(clave);
      }
    });

    // Si el campo estaba marcado como no válido, se vuelve a comprobar al escribir.
    campo.addEventListener('input', function () {
      if (campo.getAttribute('aria-invalid') === 'true') {
        validarCampo(clave);
      }
    });
  });

  /* ---------- Envío ---------- */

  formulario.addEventListener('submit', function (evento) {
    var primerNoValido = null;
    var resultados = {};

    Object.keys(campos).forEach(function (clave) {
      resultados[clave] = validarCampo(clave);
      if (resultados[clave].error && primerNoValido === null) {
        primerNoValido = campos[clave];
      }
    });

    if (primerNoValido !== null) {
      evento.preventDefault();
      primerNoValido.focus();
      return;
    }

    // Todo es válido: se añaden las formas ASCII y el formulario se envía.
    correoAscii.value = resultados.correo.ascii || '';
    webAscii.value = resultados.web.ascii || '';
  });
})();
</script>
</body>
